18	/* Data for the VPS deploy wizard.
19	 *
20	 * The one rule this file exists to keep: every number the wizard can display is
21	 * computed HERE, by the same functions that charge the card, and handed down
22	 * already worked out. The view prints; it never multiplies.
23	 *
24	 * `effectiveMonthlyCents` is built as a plan x term MATRIX rather than sent as a
25	 * rate plus a discount percent. Sending the percent would mean the browser does
26	 * `rate * (1 - pct)` — a second pricing formula, and the one that is on screen
27	 * when the customer decides. Terms are few and plans are few, so the matrix is
28	 * cheap and it cannot drift from `vpsTermPriceCents`.
29	 */
30	
31	/* Icon per image, keyed off the platform's own `family` value rather than
32	   sniffing the display name. Control panels and applications have families too
33	   (cpanel, plesk, docker, ...), so one map serves all three tabs. */
34	const ICON_BY_FAMILY: Record<string, string> = {
35	  ubuntu: "ubuntu", debian: "debian", almalinux: "osA", rocky: "osC",
36	  arch: "arch", fedora: "osB", windows: "windows", centos: "osA",
37	  docker: "docker", wordpress: "cloud", node: "nginx", nginx: "nginx",
38	  mysql: "mysql", postgres: "postgres", redis: "redis",
39	  cpanel: "gear2", plesk: "gear2", webmin: "sliders", hestiacp: "sliders",
40	  cloudpanel: "sliders", cyberpanel: "sliders", aapanel: "sliders",
41	};
42	function osIcon(family: string, category: string): string {
43	  return ICON_BY_FAMILY[family?.toLowerCase()]
44	    ?? (category === "CONTROL_PANEL" ? "sliders" : category === "APPLICATION" ? "cube" : "linux");
