47	export default async function NxDeployPage() {
48	  const user = await requireUser();
49	
50	  const [plans, oses, nodes, gamePlans, hostingPlans, emailPlans, annualPct, diskPerGbCents, ipCents, backupCents] = await Promise.all([
51	    db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
52	    /* All three categories — the design's Server settings panel has a tab per
53	       category (Operating system / Control panels / Applications), which is
54	       exactly what ImageCategory already distinguishes. They are separated in
55	       the VIEW, not filtered out here: a game-server image is a real thing you
56	       can deploy, it just is not an answer to "pick an operating system". */
57	    /* Game images are EXCLUDED from the VPS wizard. They are real deployable
58	       images, but Nxeon sells game servers as their own product with their own
59	       plans, panel and pricing — offering "Minecraft Server" as a VPS
60	       application sells the same thing twice, at the wrong price, without the
61	       game panel. Identified by `family` against the platform's own
62	       GAME_FAMILIES registry rather than by matching "... Server" in a name. */
63	    db.osTemplate.findMany({
64	      where: { active: true, NOT: { family: { in: [...GAME_FAMILIES] } } },
65	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
66	    }),
67	    // enabled only — a disabled node is not a place we can provision.
68	    db.node.findMany({ where: { enabled: true }, select: { id: true, region: true } }),
69	    // "from" prices for the service tiles — the cheapest live plan of each kind,
70	    // read from the same tables the order path prices against.
71	    // Every active tier: the wizard groups them into families itself, so one
72	    // query serves both the "from" price on the tiles and the tier picker.
73	    db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
74	    db.hostingPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
75	    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
76	    annualDiscountPct(),
77	    extraDiskPerGbCents(),
78	    dedicatedIpMonthlyCents(),
79	    backupPlusMonthlyCents(),
80	  ]);
