     3	import { useEffect, useRef } from "react";
     4	import { usePathname } from "next/navigation";
     5	
     6	/**
     7	 * Invisible page-view beacon. Mount once in the marketing layout (kind default)
     8	 * and once in the portal Shell with `kind="portal"`. On every client-side route
     9	 * change it fires a best-effort POST to /api/track. Rapid repeats of the same
    10	 * path are de-duped within the tab via sessionStorage so React strict-mode
    11	 * double-mounts and quick back/forward navigation don't double-count.
    12	 *
    13	 * Beyond the raw pageview it now also captures the behaviour the audience/funnel
    14	 * dashboard needs, all client-side and cookie-free here (the durable, consent-gated
    15	 * visitor id is minted server-side in /api/track):
    16	 *  - a per-TAB `sessionId` (sessionStorage, restarts after 30 min idle) so pageviews
    17	 *    group into sessions for "avg time on site" and bounce rate,
    18	 *  - an `isEntry` flag on the first pageview of a session (the landing page),
    19	 *  - `utm_*` params off the landing URL, remembered for the whole session so every
    20	 *    page attributes back to the ad/campaign that brought the visitor,
    21	 *  - a per-pageview id (`pvid`) plus a dwell-time "close" beacon fired on navigation
    22	 *    away and on pagehide, so each pageview gets a real time-on-page.
    23	 */
    24	export default function VisitTracker({ kind = "marketing" }: { kind?: "marketing" | "portal" }) {
    25	  const pathname = usePathname();
    26	  // The currently-open pageview whose dwell time we still owe a close beacon for.
    27	  const openRef = useRef<{ pvid: string; start: number } | null>(null);
    28	
    29	  useEffect(() => {
    30	    if (typeof window === "undefined") return;
    31	    const path = pathname || window.location.pathname || "/";
    32	
    33	    // Dedupe: skip if we already tracked this exact path within the last 30s.
    34	    const dkey = `nx_track:${kind}:${path}`;
    35	    try {
    36	      const last = Number(window.sessionStorage.getItem(dkey) ?? 0);
    37	      if (Date.now() - last < 30_000) return;
    38	      window.sessionStorage.setItem(dkey, String(Date.now()));
    39	    } catch {
    40	      /* private mode / storage disabled — just proceed without dedupe */
    41	    }
    42	
    43	    // --- Session id (per tab, 30-min idle window) + entry detection ---
    44	    const SESSION_IDLE_MS = 30 * 60_000;
    45	    let sessionId = "";
    46	    let isEntry = false;
    47	    let utm: { source?: string; medium?: string; campaign?: string; gclid?: string } = {};
    48	    try {
    49	      const now = Date.now();
    50	      const prevId = window.sessionStorage.getItem("nx_sid");
    51	      const prevTs = Number(window.sessionStorage.getItem("nx_sid_ts") ?? 0);
    52	      if (prevId && now - prevTs < SESSION_IDLE_MS) {
    53	        sessionId = prevId;
    54	        // Carry the session's captured campaign forward to every page.
    55	        try {
    56	          utm = JSON.parse(window.sessionStorage.getItem("nx_utm") ?? "{}");
    57	        } catch {
    58	          /* ignore malformed */
    59	        }
    60	      } else {
    61	        // Fresh session: this pageview is the entry/landing hit.
    62	        sessionId = genId();
    63	        isEntry = true;
    64	        const qs = new URLSearchParams(window.location.search);
    65	        const src = qs.get("utm_source") ?? undefined;
    66	        const med = qs.get("utm_medium") ?? undefined;
    67	        const camp = qs.get("utm_campaign") ?? undefined;
    68	        // Google Ads click id. Auto-tagging appends `?gclid=…` with no utm params,
    69	        // so without this those clicks would land unattributed. Fall back to Google's
    70	        // own first-party `_gcl_aw` cookie (`GCL.<ts>.<gclid>`) when the URL has none.
    71	        const gclid = qs.get("gclid") ?? readGclAw() ?? undefined;
    72	        utm = {
    73	          ...(src ? { source: src.slice(0, 120) } : {}),
    74	          ...(med ? { medium: med.slice(0, 120) } : {}),
    75	          ...(camp ? { campaign: camp.slice(0, 120) } : {}),
    76	          ...(gclid ? { gclid: gclid.slice(0, 200) } : {}),
    77	        };
    78	        window.sessionStorage.setItem("nx_sid", sessionId);
    79	        window.sessionStorage.setItem("nx_utm", JSON.stringify(utm));
    80	      }
    81	      window.sessionStorage.setItem("nx_sid_ts", String(now));
    82	    } catch {
    83	      // Storage disabled — still track the pageview, just without session grouping.
    84	      sessionId = genId();
    85	    }
    86	
    87	    // Close out the previous pageview's dwell before opening this one (SPA nav).
    88	    closeOpen();
    89	
    90	    const pvid = genId();
    91	    openRef.current = { pvid, start: Date.now() };
    92	
    93	    try {
    94	      fetch(`/api/track?k=${kind}`, {
    95	        method: "POST",
    96	        headers: { "content-type": "application/json" },
    97	        body: JSON.stringify({
    98	          path,
    99	          referrer: document.referrer || null,
   100	          sessionId,
   101	          pvid,
   102	          isEntry,
   103	          utmSource: utm.source ?? null,
   104	          utmMedium: utm.medium ?? null,
   105	          utmCampaign: utm.campaign ?? null,
   106	          gclid: utm.gclid ?? null,
   107	        }),
   108	        keepalive: true,
   109	      }).catch(() => {});
   110	    } catch {
   111	      /* fire-and-forget; never disrupt the page */
   112	    }
   113	    // pathname is the dependency; helpers are stable closures.
   114	    // eslint-disable-next-line react-hooks/exhaustive-deps
   115	  }, [pathname, kind]);
   116	
   117	  // Close the last open pageview when the tab is actually going away.
   118	  useEffect(() => {
   119	    if (typeof window === "undefined") return;
   120	    const onHide = () => closeOpen();
   121	    const onVis = () => {
