   124	    window.addEventListener("pagehide", onHide);
   125	    document.addEventListener("visibilitychange", onVis);
   126	    return () => {
   127	      window.removeEventListener("pagehide", onHide);
   128	      document.removeEventListener("visibilitychange", onVis);
   129	    };
   130	    // eslint-disable-next-line react-hooks/exhaustive-deps
   131	  }, [kind]);
   132	
   133	  /** Send the dwell time for the currently-open pageview, once. */
   134	  function closeOpen() {
   135	    const open = openRef.current;
   136	    if (!open) return;
   137	    openRef.current = null;
   138	    const dur = Date.now() - open.start;
   139	    if (dur < 250) return; // ignore instant bounces / strict-mode churn
   140	    const body = JSON.stringify({ close: true, pvid: open.pvid, dur });
   141	    try {
   142	      // sendBeacon survives unload; fall back to keepalive fetch.
   143	      if (navigator.sendBeacon) {
   144	        navigator.sendBeacon(`/api/track?k=${kind}`, new Blob([body], { type: "application/json" }));
   145	      } else {
   146	        fetch(`/api/track?k=${kind}`, {
   147	          method: "POST",
   148	          headers: { "content-type": "application/json" },
   149	          body,
   150	          keepalive: true,
   151	        }).catch(() => {});
   152	      }
   153	    } catch {
   154	      /* best-effort */
   155	    }
   156	  }
   157	
   158	  return null;
   159	}
   160	
   161	/** Read the gclid out of Google's `_gcl_aw` cookie (`GCL.<ts>.<gclid>`), if present.
   162	 *  Used as a fallback when the current URL carries no `?gclid=` — e.g. the visitor
   163	 *  clicked the ad, gtag stored the cookie, then navigated deeper before we tracked. */
   164	function readGclAw(): string | undefined {
   165	  try {
   166	    const m = document.cookie.match(/(?:^|;\s*)_gcl_aw=([^;]+)/);
   167	    if (!m) return undefined;
   168	    const parts = decodeURIComponent(m[1]).split(".");
   169	    const id = parts[parts.length - 1];
   170	    return id && id.length > 3 ? id : undefined;
   171	  } catch {
   172	    return undefined;
   173	  }
   174	}
   175	
   176	/** Small random id; prefers crypto.randomUUID, falls back for old browsers. */
   177	function genId(): string {
   178	  try {
   179	    if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
   180	  } catch {
   181	    /* ignore */
   182	  }
   183	  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
   184	}

